		/** 
		 * Tests creating a new Product.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Product");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Product" );

			try {            
				Product entity = ProductService.getProductInstance().createProduct( generateNewEntity() );
				thePrimaryKey = entity.getProductId();
				LOGGER.info( "-- Successfully created a Product with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Product. 
		 */
		public Product testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Product" );

			Product entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Product with primary key" );
			msg.append( thePrimaryKey );
			
			ProductFetchOneSummary fetchOneSummary = new ProductFetchOneSummary( thePrimaryKey );

			try {
				entity = ProductService.getProductInstance().getProduct( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Product " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Product.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Product." );

			StringBuilder msg = new StringBuilder( "Failed to update a Product : " );        
			Product entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Product." );

				// for use later on...
				thePrimaryKey = entity.getProductId();

				ProductService proxy = ProductService.getProductInstance();            
				proxy.updateProduct( entity );   

				LOGGER.info( "-- Successfully saved Product - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Product.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Product." );

			try{
			    Product entity = testRead(); 
				ProductService.getProductInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Product with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Product with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Products.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Products:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Product : " );        
			List<Product> collection  = null;

			try {
				// call the static get method on the ProductService
				collection = ProductService.getProductInstance().getAllProduct();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Product entity = null;            
					Iterator<Product> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getProductId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

